    cpi={(int(a),int(b[1:])):float(c) for line in raw for a,b,c in [line.split()]}
    years=np.arange(1953,2003)
    assert len(port)==len(fac)==50 and np.array_equal(port[:,0],years) and np.array_equal(fac[:,0],years)
